func (d MemberDraft) foundryMutation(create bool) (foundryquery.Mutation[Member], error) {
	if create && !d.fieldID.IsSet() {
		id, err := model.NewID[Member]()
		if err != nil {
			return foundryquery.Mutation[Member]{}, err
		}
		d = d.SetID(id)
	}
	var assignments []foundryquery.Assignment[Member]
	if v, set := d.fieldID.Get(); set {
		assignments = append(assignments, foundryquery.Assign[Member]("recovery_members", "id", codec.ID[Member](), v))
	}
	if v, set := d.fieldEmail.Get(); set {
		assignments = append(assignments, foundryquery.Assign[Member]("recovery_members", "email", codec.String[string](), v))
	}
	if v, set := d.fieldEmailRevision.Get(); set {
		assignments = append(assignments, foundryquery.Assign[Member]("recovery_members", "email_revision", codec.ID[challenge.RevisionOwner[Member]](), v))
	}
	if v, set := d.fieldPassword.Get(); set {
		assignments = append(assignments, foundryquery.Assign[Member]("recovery_members", "password", password.Codec(), v))
	}
	if v, set := d.fieldEmailVerified.Get(); set {
		assignments = append(assignments, foundryquery.Assign[Member]("recovery_members", "email_verified", codec.Bool[bool](), v))
	}
	if v, set := d.fieldEnabled.Get(); set {
		assignments = append(assignments, foundryquery.Assign[Member]("recovery_members", "enabled", codec.Bool[bool](), v))
	}
	return foundryquery.Change(assignments...), nil
}

