// CompareMember is the generated lifecycle comparison boundary. Pass stored snapshots and the effective assignment draft; its values are not transformed or compared to the result. Both snapshots, when present, must have the same primary key. This function performs no database work or automatic capture.
func CompareMember(before, after foundryvalue.Optional[Member], assigned MemberDraft) (MemberChanges, error) {
	before = foundryMemberSnapshot(before)
	after = foundryMemberSnapshot(after)
	var changes MemberChanges
	var err error
	changes.fields.ID, err = lifecycle.CompareModelField(codec.ID[Member](), before, after, assigned.fieldID.IsSet(), func(item Member) model.ID[Member] { return item.ID })
	if err != nil {
		return MemberChanges{}, fmt.Errorf("compare Member.ID: %w", err)
	}
	if before.IsSet() && after.IsSet() && (changes.fields.ID.Changed() || changes.fields.ID.Assigned()) {
		return MemberChanges{}, foundryfault.New(foundryfault.Invalid, "model change cannot replace or assign its existing primary key")
	}
	changes.fields.Email, err = lifecycle.CompareModelField(codec.String[string](), before, after, assigned.fieldEmail.IsSet(), func(item Member) string { return item.Email })
	if err != nil {
		return MemberChanges{}, fmt.Errorf("compare Member.Email: %w", err)
	}
	changes.fields.EmailRevision, err = lifecycle.CompareModelField(codec.ID[challenge.RevisionOwner[Member]](), before, after, assigned.fieldEmailRevision.IsSet(), func(item Member) challenge.Revision[Member] { return item.EmailRevision })
	if err != nil {
		return MemberChanges{}, fmt.Errorf("compare Member.EmailRevision: %w", err)
	}
	changes.fields.Password, err = lifecycle.CompareModelField(password.Codec(), before, after, assigned.fieldPassword.IsSet(), func(item Member) password.Hash { return item.Password })
	if err != nil {
		return MemberChanges{}, fmt.Errorf("compare Member.Password: %w", err)
	}
	changes.fields.EmailVerified, err = lifecycle.CompareModelField(codec.Bool[bool](), before, after, assigned.fieldEmailVerified.IsSet(), func(item Member) bool { return item.EmailVerified })
	if err != nil {
		return MemberChanges{}, fmt.Errorf("compare Member.EmailVerified: %w", err)
	}
	changes.fields.Enabled, err = lifecycle.CompareModelField(codec.Bool[bool](), before, after, assigned.fieldEnabled.IsSet(), func(item Member) bool { return item.Enabled })
	if err != nil {
		return MemberChanges{}, fmt.Errorf("compare Member.Enabled: %w", err)
	}
	changes.before = before
	changes.after = after
	return changes, nil
}
func foundryMemberSnapshot(snapshot foundryvalue.Optional[Member]) foundryvalue.Optional[Member] {
	item, present := snapshot.Get()
	if !present {
		return foundryvalue.Optional[Member]{}
	}
	return foundryvalue.Set(Member{
		ID:            item.ID,
		Email:         item.Email,
		EmailRevision: item.EmailRevision,
		Password:      item.Password,
		EmailVerified: item.EmailVerified,
		Enabled:       item.Enabled,
	})
}

