// Audit captures this operation's existing stored changes without getters, mutators or additional database work.
// Updates, soft deletes and restorations record assigned or changed fields plus the key; create and delete record every field.
// Standalone Compare results have no captured operation and cannot become lifecycle audit records.
func (changes MemberChanges) Audit(policy MemberAuditPolicy) (record.Model[Member, model.ID[Member]], error) {
	operation, present := changes.operation.Get()
	if !present {
		return record.Model[Member, model.ID[Member]]{}, foundryfault.New(foundryfault.Missing, "audit requires captured model changes")
	}
	item, present := changes.after.Get()
	if !present {
		item, present = changes.before.Get()
	}
	if !present {
		return record.Model[Member, model.ID[Member]]{}, foundryfault.New(foundryfault.Missing, "audit requires a stored model snapshot")
	}
	builder, err := record.NewBuilder(item.FoundryReference(), operation, "id", policy.ID)
	if err != nil {
		return record.Model[Member, model.ID[Member]]{}, err
	}
	if err = record.Capture(builder, "id", codec.ID[Member](), changes.fields.ID, policy.ID); err != nil {
		return record.Model[Member, model.ID[Member]]{}, err
	}
	if err = record.Capture(builder, "email", codec.String[string](), changes.fields.Email, policy.Email); err != nil {
		return record.Model[Member, model.ID[Member]]{}, err
	}
	if err = record.Capture(builder, "email_revision", codec.ID[challenge.RevisionOwner[Member]](), changes.fields.EmailRevision, policy.EmailRevision); err != nil {
		return record.Model[Member, model.ID[Member]]{}, err
	}
	if err = record.Capture(builder, "password", password.Codec(), changes.fields.Password, policy.Password); err != nil {
		return record.Model[Member, model.ID[Member]]{}, err
	}
	if err = record.Capture(builder, "email_verified", codec.Bool[bool](), changes.fields.EmailVerified, policy.EmailVerified); err != nil {
		return record.Model[Member, model.ID[Member]]{}, err
	}
	if err = record.Capture(builder, "enabled", codec.Bool[bool](), changes.fields.Enabled, policy.Enabled); err != nil {
		return record.Model[Member, model.ID[Member]]{}, err
	}
	return builder.Build()
}

